func (this *Test_org_eclipse_swt_widgets_Display) Test_sleep() {
	var display *swt.Display = swt.NewDisplay()
	{
		defer func() {
			display.Dispose()
		}()
		var thread any
		var eventQueued bool
		for display.ReadAndDispatch() {
		}
		thread = any(jrt.NewThread(jrt.NewRunnable(func() {
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if func() bool {
						switch r.(type) {
						case *jrt.InterruptedException:
							return true
						}
						return false
					}() {
						ex := r.(*jrt.InterruptedException)
						_ = ex
					} else {
						panic(r)
					}
				}()
				jrt.Sleep(int64(3000))
			}()
			display.Wake()
		})))
		jrt.ThreadStart(thread)
		eventQueued = display.Sleep()
		for display.ReadAndDispatch() {
		}
		thread = any(jrt.NewThread(jrt.NewRunnable(func() {
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if func() bool {
						switch r.(type) {
						case *jrt.InterruptedException:
							return true
						}
						return false
					}() {
						ex := r.(*jrt.InterruptedException)
						_ = ex
					} else {
						panic(r)
					}
				}()
				jrt.Sleep(int64(3000))
			}()
			display.SyncExec(jrt.NewRunnable(func() {
				var s *swt.Shell = swt.NewShellDisplay(display)
				s.Open()
				s.Dispose()
			}))
		})))
		jrt.ThreadStart(thread)
		eventQueued = display.Sleep()
		junit.AssertTrue(eventQueued)
	}
}

